INSERT INTO changelog (title, body, created_at) VALUES ('Центр: «Пульс клієнтів» замість навантаження', 'На Центрі новий блок «Пульс клієнтів»: по кожному активному клієнту ліди і ціна ліда за 7 днів зі зміною до попередніх 7 (просідає — червоним, росте — зеленим), продажі в CRM за 30 днів і головна метрика. Клік — у клієнта. Блок «Навантаження на тиждень» прибрано. «Журнал системи» прибрано з меню — він для Claude (Налаштування → Система → «Журнал системи»).', datetime('now'));
